package billing

import (
	"log"
	"time"
)

// Deliberate tuning smell: renewInterval is set equal to leaseTTL instead of
// a fraction of it, leaving almost no margin before the lease can expire
// out from under a live leader.
const (
	leaseTTL      = 15 * time.Second
	renewInterval = 15 * time.Second
)

// LockStore models a Redis/etcd-style distributed lock with lease semantics.
// TryAcquire returns both whether leadership was won and a monotonically
// increasing fencing term for the winning attempt.
type LockStore interface {
	TryAcquire(lockKey string, ttl time.Duration) (acquired bool, term int64, err error)
	Renew(lockKey string, ttl time.Duration) error
}

// PendingOrder is a single billing-sweep line item awaiting a charge.
type PendingOrder struct {
	OrderID string
	Amount  float64
}

// NightlyBillingSweeper elects a single leader to run the nightly billing job.
type NightlyBillingSweeper struct {
	store    LockStore
	lockKey  string
	isLeader bool
	term     int64 // captured at acquire time, then never referenced again
}

func NewNightlyBillingSweeper(store LockStore) *NightlyBillingSweeper {
	return &NightlyBillingSweeper{store: store, lockKey: "billing-sweep-leader"}
}

// Start acquires leadership, spins the renew loop, then runs the sweep.
func (s *NightlyBillingSweeper) Start(orders []PendingOrder) {
	acquired, term, err := s.store.TryAcquire(s.lockKey, leaseTTL)
	if err != nil {
		log.Printf("acquire failed: %v", err)
		return
	}
	if !acquired {
		log.Println("another node is leader, exiting")
		return
	}

	// term is stored on the struct but is dropped here — it never travels
	// downstream with the side effect it is supposed to fence.
	s.isLeader = true
	s.term = term

	go s.renewLoop()

	s.runSweep(orders)
}

// renewLoop keeps the lease alive on a fixed tick. On a renew failure it
// only logs — there is no fast re-check of leadership on the hot path, and
// no signal is sent to stop an in-flight sweep.
func (s *NightlyBillingSweeper) renewLoop() {
	ticker := time.NewTicker(renewInterval)
	defer ticker.Stop()

	for range ticker.C {
		if err := s.store.Renew(s.lockKey, leaseTTL); err != nil {
			log.Printf("renew failed, lease may be lost: %v", err)
		}
	}
}

// runSweep walks pending orders and charges each one while this node
// believes it is leader. isLeader is a plain local bool set once at
// acquire time — it is never re-read from the lock store at the moment
// of the charge, so a goroutine that stalls (e.g. a long GC pause) past
// leaseTTL will resume and keep charging as if nothing happened.
func (s *NightlyBillingSweeper) runSweep(orders []PendingOrder) {
	for _, order := range orders {
		if s.isLeader {
			if err := chargeCustomer(order.OrderID, order.Amount); err != nil {
				log.Printf("charge failed for order %s: %v", order.OrderID, err)
			}
		}
	}
}

// chargeCustomer is the non-idempotent downstream side effect. Its signature
// takes only an order id and amount — there is no fencing term parameter and
// no idempotency key, so the billing tier cannot tell a legitimate charge
// apart from a stale replay fired by an expired leader.
func chargeCustomer(orderID string, amount float64) error {
	return paymentGatewayClient.Charge(orderID, amount)
}

var paymentGatewayClient interface {
	Charge(orderID string, amount float64) error
}
